package com.bank.dsa;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: average monthly balance over three months.
public class AverageDemo {
    private static final Logger log = Logger.getLogger(AverageDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AverageBalanceService service = new AverageBalanceService();

        BigDecimal jan = new BigDecimal("10000.00");  // A
        BigDecimal feb = new BigDecimal("20000.00");  // B
        BigDecimal mar = new BigDecimal("30000.00");  // C
        BigDecimal avg = service.average(jan, feb, mar);

        log.info(() -> "Rajesh SAV2001 average monthly balance = Rs." + avg);
    }
}

