class AverageBalanceService {
    private static final BigDecimal THREE = new BigDecimal("3");

    // sum = A + B + C; average = sum / 3 (rounded to paisa, half-even).
    BigDecimal average(BigDecimal a, BigDecimal b, BigDecimal c) {
        if (a == null || b == null || c == null) {
            throw new IllegalArgumentException("Balances must not be null");
        }
        BigDecimal sum = a.add(b).add(c);                 // exact sum
        return sum.divide(THREE, 2, java.math.RoundingMode.HALF_EVEN);  // safe division
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
